<script>
(() => {
    const modes={
        free:{note:'Start anywhere. There is no right way to write.',title:"What's on your mind today?",description:'No perfect words needed. Start wherever you are.',placeholder:'Let the first sentence be simple. You can always add more.',ideas:['What is taking up space in my mind?','Right now I notice...'],prompts:["One thing that's been on my mind lately is...",'A feeling I want to make room for is...','If I could be honest with myself, I would say...']},
        guided:{note:'A gentle structure for noticing what happened and what you need.',title:'Take a guided pause.',description:'Use the questions as a path, or leave them behind whenever you want.',placeholder:'What happened? How did it feel? What might help next?',ideas:['Today felt difficult because...','What I need next is...'],prompts:['Something that felt harder than expected was...','The support I could use right now is...','One small next step I can choose is...']},
        good:{note:'Make room for small moments that felt warm, steady, or kind.',title:'Notice a little good thing.',description:'It can be ordinary. A good moment does not need to be big to count.',placeholder:'A small thing I appreciated today was...',ideas:['Someone or something I appreciated...','A moment that felt lighter...'],prompts:['A small moment that made me smile was...','Something my future self may appreciate is...','Today I want to remember...']}
    };
    const form=document.querySelector('[data-journal-form]'),panel=document.querySelector('[data-journal-form-panel]'),editor=document.querySelector('[data-journal-editor]'),titleInput=document.querySelector('[data-journal-title]'),methodInput=document.querySelector('[data-journal-method]'),moodInput=document.querySelector('[data-journal-mood-input]'),submit=document.querySelector('[data-journal-submit]'),submitLabel=document.querySelector('[data-journal-submit-label]'),feedback=document.querySelector('[data-journal-feedback]'),count=document.querySelector('[data-journal-count]'),modeNote=document.querySelector('[data-journal-mode-note]'),modeTitle=document.querySelector('[data-journal-form-title]'),modeDescription=document.querySelector('[data-journal-form-description]'),quickIdeas=document.querySelector('[data-journal-quick-ideas]'),promptText=document.querySelector('[data-journal-prompt-text]'),promptIndex=document.querySelector('[data-journal-prompt-index]');
    let activeMode='free',promptPosition=0;
    const promptDisclosure=document.querySelector('.journal-prompt-disclosure');promptDisclosure?.addEventListener('toggle',()=>{const assistiveText=promptDisclosure.querySelector('.sr-only');if(assistiveText)assistiveText.textContent=promptDisclosure.open?'Hide optional writing prompts':'Show optional writing prompts';});
    const insertText=(text)=>{if(!editor||!text)return;editor.value=editor.value.trim()?`${editor.value.trim()}\n\n${text} `:`${text} `;editor.focus();editor.setSelectionRange(editor.value.length,editor.value.length);updateFeedback();};
    const updateFeedback=()=>{if(!editor)return;const length=editor.value.length;if(count)count.textContent=`${length} / 5000`;if(feedback){feedback.classList.toggle('is-ready',length>=20);feedback.textContent=length===0?'Writing can begin with one honest sentence.':(length<20?'A little more detail can help you remember this moment.':'That is a thoughtful start. Keep going if it feels useful.');}};
    const renderPrompt=()=>{const prompts=modes[activeMode].prompts;promptPosition=promptPosition%prompts.length;if(promptText)promptText.textContent=prompts[promptPosition];if(promptIndex)promptIndex.textContent=`${String(promptPosition+1).padStart(2,'0')} / ${String(prompts.length).padStart(2,'0')}`;};
    const applyMode=(mode)=>{if(!modes[mode])return;activeMode=mode;const config=modes[mode];document.querySelectorAll('[data-journal-mode]').forEach((tab)=>{const active=tab.dataset.journalMode===mode;tab.classList.toggle('is-active',active);tab.setAttribute('aria-pressed',active?'true':'false');});if(modeNote)modeNote.textContent=config.note;if(modeTitle&&!panel?.classList.contains('is-editing'))modeTitle.textContent=config.title;if(modeDescription&&!panel?.classList.contains('is-editing'))modeDescription.textContent=config.description;if(editor&&!panel?.classList.contains('is-editing'))editor.placeholder=config.placeholder;if(quickIdeas){quickIdeas.replaceChildren(...config.ideas.map((idea)=>{const button=document.createElement('button');button.type='button';button.className='journal-idea';button.textContent=idea;button.addEventListener('click',()=>insertText(idea+' '));return button;}));}promptPosition=0;renderPrompt();};
    const selectMood=(mood)=>{if(!moodInput)return;moodInput.value=mood||'';document.querySelectorAll('[data-journal-mood]').forEach((button)=>button.classList.toggle('is-selected',button.dataset.journalMood===mood));};
    const resetEditor=()=>{if(!form||!panel)return;panel.classList.remove('is-editing');form.action="{{ route('student.store-entry') }}";if(methodInput)methodInput.disabled=true;if(submitLabel)submitLabel.textContent='Save reflection';if(modeTitle)modeTitle.textContent=modes[activeMode].title;if(modeDescription)modeDescription.textContent=modes[activeMode].description;if(editor)editor.placeholder=modes[activeMode].placeholder;form.reset();selectMood('');updateFeedback();};
    const editEntry=(card)=>{if(!form||!panel||!card)return;panel.classList.add('is-editing');form.action=card.dataset.updateUrl;if(methodInput)methodInput.disabled=false;if(titleInput)titleInput.value=card.dataset.entryTitle||'';if(editor)editor.value=card.dataset.entryBody||'';selectMood(card.dataset.entryMood||'');if(modeTitle)modeTitle.textContent='Continue your reflection.';if(modeDescription)modeDescription.textContent='Edit your saved words. This will not trigger a new AI analysis.';if(submitLabel)submitLabel.textContent='Save changes';updateFeedback();panel.scrollIntoView({behavior:'smooth',block:'start'});setTimeout(()=>editor?.focus(),250);};
    document.querySelectorAll('[data-journal-mode]').forEach((tab)=>tab.addEventListener('click',()=>applyMode(tab.dataset.journalMode)));document.querySelectorAll('[data-journal-mood]').forEach((button)=>button.addEventListener('click',()=>selectMood(moodInput?.value===button.dataset.journalMood?'':button.dataset.journalMood)));document.querySelector('[data-journal-next-prompt]')?.addEventListener('click',()=>{promptPosition+=1;renderPrompt();});document.querySelector('[data-journal-use-prompt]')?.addEventListener('click',()=>insertText(promptText?.textContent||''));document.querySelector('[data-journal-cancel]')?.addEventListener('click',resetEditor);editor?.addEventListener('input',updateFeedback);form?.addEventListener('reset',()=>setTimeout(()=>{selectMood('');updateFeedback();},0));form?.addEventListener('submit',()=>{submit?.setAttribute('disabled','disabled');submit?.classList.add('is-loading');});document.querySelectorAll('[data-journal-open]').forEach((button)=>button.addEventListener('click',()=>{const card=button.closest('[data-journal-entry]');const open=card?.classList.toggle('is-open');button.textContent=open?'Close':'Open';}));document.querySelectorAll('[data-journal-edit]').forEach((button)=>button.addEventListener('click',()=>editEntry(button.closest('[data-journal-entry]'))));
    const search=document.querySelector('[data-journal-search]'),sort=document.querySelector('[data-journal-sort]'),grid=document.querySelector('[data-journal-entries]'),noResults=document.querySelector('[data-journal-no-results]');
    const refreshEntries=()=>{if(!grid)return;const query=(search?.value||'').trim().toLowerCase();const cards=[...grid.querySelectorAll('[data-journal-entry]')];cards.sort((a,b)=>{const delta=Number(a.dataset.entryTime||0)-Number(b.dataset.entryTime||0);return sort?.value==='oldest'?delta:-delta;});cards.forEach((card)=>{card.hidden=!!query&&!(card.dataset.entryText||'').includes(query);grid.appendChild(card);});if(noResults)noResults.hidden=cards.some((card)=>!card.hidden)||!query;};search?.addEventListener('input',refreshEntries);sort?.addEventListener('change',refreshEntries);applyMode('free');updateFeedback();
})();
</script>
@endsection
